DROP TABLE IF EXISTS `drive_roles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `drive_roles` (
  `role_id` int(11) NOT NULL AUTO_INCREMENT,
  `drive_id` int(11) DEFAULT NULL,
  `designation_name` varchar(100) DEFAULT NULL,
  `eligible_courses` text DEFAULT NULL,
  `min_percentage` decimal(5,2) DEFAULT NULL,
  `ctc` varchar(50) DEFAULT NULL,
  `stipend` text DEFAULT NULL,
  `work_timings` varchar(255) DEFAULT NULL,
  `bond_details` text DEFAULT NULL,
  `selection_process` text DEFAULT NULL,
  `other_benefits` text DEFAULT NULL,
  `form_fields` text DEFAULT NULL,
  `offer_type` varchar(50) DEFAULT NULL,
  `sector` varchar(100) DEFAULT NULL,
  `is_finished` tinyint(1) DEFAULT 0,
  `close_date` date DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`role_id`),
  KEY `drive_id` (`drive_id`),
  KEY `idx_roles_id` (`role_id`),
  CONSTRAINT `drive_roles_ibfk_1` FOREIGN KEY (`drive_id`) REFERENCES `drives` (`drive_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=978 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

