CREATE TABLE `drives` (
  `drive_id` int(11) NOT NULL AUTO_INCREMENT,
  `company_name` varchar(100) DEFAULT NULL,
  `company_sector` varchar(100) DEFAULT NULL,
  `company_url` varchar(255) DEFAULT NULL,
  `drive_no` varchar(50) DEFAULT NULL,
  `open_date` datetime NOT NULL,
  `close_date` datetime NOT NULL,
  `jd_file` longtext DEFAULT NULL,
  `form_link` varchar(255) DEFAULT NULL,
  `form_fields` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `extra_details` longtext DEFAULT NULL,
  `graduating_year` varchar(50) DEFAULT NULL,
  `work_location` varchar(255) DEFAULT NULL,
  `jd_link` text DEFAULT NULL,
  `created_by` varchar(100) DEFAULT NULL,
  `show_to_internship` tinyint(1) DEFAULT 1,
  `show_to_vantage` tinyint(1) DEFAULT 1,
  `show_to_placement` tinyint(1) DEFAULT 1,
  `academic_year` varchar(20) DEFAULT '2025-2026',
  PRIMARY KEY (`drive_id`),
  KEY `idx_drives_id` (`drive_id`)
) ENGINE=InnoDB AUTO_INCREMENT=702 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
