CREATE TABLE `students` (
  `student_id` int(11) NOT NULL AUTO_INCREMENT,
  `upid` varchar(50) DEFAULT NULL,
  `program_type` varchar(50) DEFAULT NULL,
  `program` varchar(50) DEFAULT NULL,
  `course` varchar(100) DEFAULT NULL,
  `class` varchar(50) DEFAULT NULL,
  `reg_no` varchar(50) DEFAULT NULL,
  `student_name` varchar(100) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `password_hash` varchar(255) DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `last_login` timestamp NULL DEFAULT NULL,
  `email_verified` tinyint(1) DEFAULT 0,
  `phone_no` varchar(20) DEFAULT NULL,
  `applied_date` date DEFAULT NULL,
  `batch` varchar(20) DEFAULT NULL,
  `placed_status` enum('placed','not_placed','blocked','rejected','pending') DEFAULT 'not_placed',
  `allow_reapply` enum('yes','no') DEFAULT 'no',
  `comment` text DEFAULT NULL,
  `company_name` varchar(100) DEFAULT NULL,
  `role` varchar(100) DEFAULT NULL,
  `offer_type` varchar(100) DEFAULT NULL,
  `ctc` varchar(50) DEFAULT NULL,
  `percentage` float DEFAULT NULL,
  `comments` text DEFAULT NULL,
  `year_of_passing` int(11) DEFAULT NULL,
  `academic_year` varchar(20) DEFAULT NULL,
  `vantage_participant` enum('yes','no') DEFAULT 'no' COMMENT 'Tracks if student is registered for Vantage event',
  `vantage_placed` enum('yes','no') DEFAULT 'no' COMMENT 'Tracks if student got placed through Vantage',
  `placement_category` enum('full-time','internship','vantage','none') DEFAULT 'none' COMMENT 'Category of placement opportunity student is eligible for',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `Offcampus_selection` enum('unknown','not_placed','placed') DEFAULT 'unknown' COMMENT 'Off-campus placement status',
  `editable_comment` text DEFAULT NULL COMMENT 'Off-campus placement comments/notes',
  PRIMARY KEY (`student_id`),
  UNIQUE KEY `upid` (`upid`),
  UNIQUE KEY `reg_no` (`reg_no`),
  KEY `idx_students_batch` (`batch`),
  KEY `idx_students_regno` (`reg_no`),
  KEY `idx_students_year` (`year_of_passing`),
  KEY `idx_students_upid` (`upid`),
  KEY `idx_student_email` (`email`),
  KEY `idx_vantage_participant` (`vantage_participant`),
  KEY `idx_vantage_placed` (`vantage_placed`),
  KEY `idx_placement_category` (`placement_category`)
) ENGINE=InnoDB AUTO_INCREMENT=5612 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `students`
--

LOCK TABLES `students` WRITE;
/*!40000 ALTER TABLE `students` DISABLE KEYS */;
